class DiagonalLayout extends Layout [
    step: number = 16,
    place() {
        let i = 0
        return this.laid().map((c) => {
            const box = ({ x: i * this.step, y: i * this.step })
            if (c.visible) i = i + 1
            return box
            })
        }
    ]

